def solve(inp, seed=None):
    h=len(inp); w=len(inp[0])
    # find box border of 3s
    rows=[i for i,r in enumerate(inp) if 3 in r]
    cols=[j for j in range(w) if any(r[j]==3 for r in inp)]
    r0,r1=min(rows),max(rows); c0,c1=min(cols),max(cols)
    out=[r[:] for r in inp]
    seeds=[]
    for i in range(r0+1,r1):
        for j in range(c0+1,c1):
            if inp[i][j]==3: seeds.append((i,j))
    if not seeds: return None
    si=sum(s[0] for s in seeds)//len(seeds); sj=sum(s[1] for s in seeds)//len(seeds)
    for i in range(r0+1,r1):
        for j in range(c0+1,c1):
            if out[i][j]!=0: continue
            d=max(abs(i-si),abs(j-sj))
            out[i][j]=2 if d%2==0 else 4
    return out
